<template>
    <div class="stock-page">
        <header class="manager-heading"><div><span class="eyebrow">KHO & NGUYÊN LIỆU</span><h2>{{ ingredientsMode ? 'Quản lý nguyên liệu' : 'Quản lý kho hàng' }}</h2><p>{{ ingredientsMode ? 'Danh sách nguyên liệu, đơn vị tính và ngưỡng tồn tối thiểu.' : 'Nhập theo phiếu, ghi nhận xuất và hao hụt, xem số tồn đã ghi nhận.' }}</p></div><button v-if="ingredientsMode" class="manager-button primary" :disabled="loading" @click="edit()">Thêm nguyên liệu</button><RouterLink v-else class="manager-button primary" to="/staff/manager/stock-imports">Tạo phiếu nhập</RouterLink></header>
        <p v-if="!ingredientsMode" class="manager-notice">Số tồn bên dưới lấy từ lần bếp chốt gần nhất cộng các giao dịch kho đã ghi; chưa trừ nguyên liệu đã dùng cho đơn trong ngày. <RouterLink to="/staff/manager/daily-stock">Xem sổ kho ngày</RouterLink>.</p>
        <div class="metrics"><div><span>Nguyên liệu đang sử dụng</span><strong>{{ items.filter(i => i.is_active).length }}</strong></div><div><span>Dưới ngưỡng / hết hàng</span><strong>{{ items.filter(i => i.is_active && i.quantity_in_stock <= i.min_stock_level).length }}</strong></div><div><span>Nguyên liệu đã hết</span><strong>{{ items.filter(i => i.is_active && i.quantity_in_stock === 0).length }}</strong></div></div>
        <div class="filters"><input v-model="search" placeholder="Tìm mã hoặc tên nguyên liệu…" aria-label="Tìm nguyên liệu" /><select v-model="status" aria-label="Lọc tồn kho"><option value="all">Tất cả nguyên liệu</option><option value="active">Đang sử dụng</option><option value="low">Dưới ngưỡng / hết hàng</option><option value="inactive">Ngừng sử dụng</option></select><button class="manager-button" :disabled="loading" @click="refresh()">Làm mới</button><RouterLink :to="ingredientsMode ? '/staff/manager/inventory' : '/staff/manager/ingredients'">{{ ingredientsMode ? 'Xem kho hàng' : 'Danh sách nguyên liệu' }}</RouterLink></div>
        <p v-if="success" class="manager-notice" role="status">{{ success }}</p><p v-if="error" class="manager-notice error" role="alert">{{ error }}</p><p v-if="loading" class="manager-notice" role="status">Đang tải dữ liệu…</p>
        <template v-else-if="!error"><p v-if="!filtered.length" class="manager-notice">Không có nguyên liệu phù hợp.</p><div v-else class="table-wrap"><table><thead><tr><th>Nguyên liệu</th><th>Đơn vị</th><th>Tồn ghi nhận</th><th>Tối thiểu</th><th>{{ ingredientsMode ? 'Nhà cung cấp' : 'Giá nhập gần nhất' }}</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="i in visible" :key="i.id"><td><strong>{{ i.name }}</strong><small>{{ i.code }}</small></td><td>{{ i.unit }}</td><td class="number">{{ number(i.quantity_in_stock) }}</td><td class="number">{{ number(i.min_stock_level) }}</td><td>{{ ingredientsMode ? i.supplier_name || 'Chưa chọn' : number(i.import_price) + ' đ' }}</td><td><span class="tag" :class="{ warn: i.is_active && i.quantity_in_stock <= i.min_stock_level }">{{ !i.is_active ? 'Ngừng sử dụng' : i.quantity_in_stock === 0 ? 'Hết hàng' : i.quantity_in_stock <= i.min_stock_level ? 'Cần bổ sung' : 'Đủ hàng' }}</span></td><td><div class="actions"><button v-if="ingredientsMode" class="manager-button" @click="edit(i)">Chỉnh sửa</button><template v-else><button class="manager-button" @click="movement('EXPORT', i)">Trả / xuất</button><button class="manager-button" @click="movement('WASTE', i)">Hủy / hỏng</button></template></div></td></tr></tbody></table></div><div v-if="filtered.length > 15" class="pagination"><button :disabled="page === 1" @click="page--">Trước</button><span>{{ page }} / {{ Math.ceil(filtered.length / 15) }}</span><button :disabled="page * 15 >= filtered.length" @click="page++">Sau</button></div></template>
        <section v-if="!ingredientsMode" class="history"><h3>Lịch sử nhập xuất và kiểm kê</h3><p class="help">Phiếu đã ghi nhận được giữ nguyên. Khi cần sửa số tồn, lập phiếu kiểm kê kèm lý do.</p><div class="filters"><select v-model="historyFilter.ingredient_id" aria-label="Nguyên liệu trong lịch sử"><option value="">Tất cả nguyên liệu</option><option v-for="i in items" :key="i.id" :value="i.id">{{ i.code }} · {{ i.name }}</option></select><select v-model="historyFilter.type" aria-label="Loại phiếu"><option value="">Tất cả loại phiếu</option><option v-for="(label, type) in types" :key="type" :value="type">{{ label }}</option></select><label>Từ ngày<input v-model="historyFilter.from" type="date" /></label><label>Đến ngày<input v-model="historyFilter.to" type="date" /></label><button class="manager-button" :disabled="historyLoading" @click="loadHistory(1)">Tra cứu</button></div><p v-if="historyError" class="manager-notice error" role="alert">{{ historyError }}</p><p v-if="historyLoading" role="status">Đang tải lịch sử…</p><template v-else-if="!historyError"><div v-if="transactions.length" class="table-wrap"><table><thead><tr><th>Phiếu / thời gian</th><th>Nguyên liệu</th><th>Loại phiếu</th><th>Số lượng</th><th>Tồn trước → sau</th><th>Người thực hiện / lý do</th></tr></thead><tbody><tr v-for="t in transactions" :key="t.id"><td><strong>NK-{{ String(t.id).padStart(6, '0') }}</strong><small>{{ date(t.transacted_at) }}</small></td><td>{{ t.name }}<small>{{ t.code }} · {{ t.unit }}</small></td><td>{{ types[t.type] }}</td><td>{{ Number(t.quantity) > 0 ? '+' : '−' }}{{ number(Math.abs(Number(t.quantity))) }}</td><td>{{ t.stock_before == null ? '—' : number(t.stock_before) }} → {{ t.stock_after == null ? '—' : number(t.stock_after) }}</td><td>{{ t.performed_name || 'Không xác định' }}<small class="note">{{ t.reason_code ? (reasonLabels[t.reason_code] || t.reason_code) + ' · ' : '' }}{{ t.note }}</small></td></tr></tbody></table></div><p v-else class="manager-notice">Chưa có phiếu trong khoảng tra cứu.</p><div v-if="lastPage > 1" class="pagination"><button :disabled="historyPage <= 1" @click="loadHistory(historyPage - 1)">Trước</button><span>{{ historyPage }} / {{ lastPage }}</span><button :disabled="historyPage >= lastPage" @click="loadHistory(historyPage + 1)">Sau</button></div></template></section>
        <dialog ref="dialog" @cancel="cancel"><form @submit.prevent="save"><header><h3>{{ editing ? (editId ? 'Sửa nguyên liệu' : 'Thêm nguyên liệu') : types[tx.type] }}</h3><button type="button" :disabled="saving" @click="close">Đóng</button></header><div class="form-body"><p v-if="formError" class="manager-notice error" role="alert">{{ formError }}</p><fieldset :disabled="saving"><template v-if="editing"><label>Mã nguyên liệu<input v-model="form.code" required maxlength="30" pattern="[A-Za-z0-9_-]+" /></label><label>Tên nguyên liệu<input v-model="form.name" required maxlength="150" /></label><label>Đơn vị tính<input v-model="form.unit" required maxlength="20" placeholder="kg, lít, gói, quả…" /></label><label>Tồn tối thiểu<input v-model.number="form.min_stock_level" type="number" min="0" step="0.01" max="9999999999.99" required /></label><label>Nhà cung cấp<select v-model="form.supplier_id"><option :value="null">Chưa chọn</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label class="check"><input v-model="form.is_active" type="checkbox" /> Đang sử dụng</label><p class="help">Nguyên liệu mới có tồn bằng 0. Dùng Nhập kho để ghi nhận số lượng ban đầu và lịch sử.</p></template><template v-else><label>Nguyên liệu<select v-model.number="tx.ingredient_id" required @change="selectIngredient"><option :value="0" disabled>Chọn nguyên liệu</option><option v-for="i in items" :key="i.id" :value="i.id" >{{ i.code }} · {{ i.name }} ({{ i.unit }})</option></select></label><p v-if="selected" class="manager-notice">Tồn ghi nhận: <strong>{{ number(tx.expected_stock) }} {{ selected.unit }}</strong></p><label>Số lượng<input v-model.number="tx.quantity" type="number" min="0.01" max="9999999999.99" step="0.01" required /></label><label>Lý do<select v-model="tx.reason_code" required><template v-if="tx.type === 'EXPORT'"><option value="SUPPLIER_RETURN">Trả nhà cung cấp</option><option value="OTHER_OUT">Xuất khác</option></template><template v-else><option value="DAMAGED">Hư hỏng</option><option value="EXPIRED">Hết hạn</option><option value="OTHER_WASTE">Hủy khác</option></template></select></label><label>Ghi chú / chứng từ<textarea v-model="tx.note" required maxlength="2000" rows="3" placeholder="Ví dụ: số phiếu trả hàng, lý do hủy, người bàn giao…" /></label><p class="help">Số lượng được ghi theo đúng đơn vị của nguyên liệu.</p></template></fieldset></div><footer><button type="button" class="manager-button" :disabled="saving" @click="close">Hủy</button><button class="manager-button primary" :disabled="saving || (!editing && !tx.ingredient_id)">{{ saving ? 'Đang lưu…' : 'Lưu' }}</button></footer></form></dialog>
    </div>
</template>
<script setup lang="ts">
import { beginRead } from '@/utils/realtime'
const liveReads = {}
import { useRealtimeRefresh } from '@/composables/useRealtimeRefresh'
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import api from '@/api/client'
interface Ingredient { id: number; code: string; name: string; unit: string; quantity_in_stock: number; min_stock_level: number; import_price: number; supplier_id: number | null; supplier_name: string | null; is_active: boolean }
type TxType = 'IMPORT' | 'EXPORT' | 'WASTE' | 'ADJUSTMENT'
interface Transaction { id: number; code: string; name: string; unit: string; type: TxType; quantity: number; stock_before: number | null; stock_after: number | null; performed_name: string | null; reason_code: string | null; note: string; transacted_at: string }
const types: Record<TxType, string> = { IMPORT: 'Nhập kho', EXPORT: 'Xuất kho', WASTE: 'Hao hụt / hủy', ADJUSTMENT: 'Kiểm kê' }
const reasonLabels: Record<string, string> = { SUPPLIER_RETURN: 'Trả nhà cung cấp', OTHER_OUT: 'Xuất khác', DAMAGED: 'Hư hỏng', EXPIRED: 'Hết hạn', OTHER_WASTE: 'Hủy khác' }
const route = useRoute(), ingredientsMode = computed(() => route.path.endsWith('/ingredients'))
const items = ref<Ingredient[]>([]), suppliers = ref<{ id: number; name: string }[]>([]), loading = ref(false), error = ref(''), success = ref('')
const search = ref(''), status = ref('all'), page = ref(1)
const filtered = computed(() => items.value.filter(i => `${i.code} ${i.name}`.toLowerCase().includes(search.value.trim().toLowerCase()) && (status.value === 'all' || (status.value === 'active' ? i.is_active : status.value === 'inactive' ? !i.is_active : i.is_active && i.quantity_in_stock <= i.min_stock_level))))
const visible = computed(() => filtered.value.slice((page.value - 1) * 15, page.value * 15))
const dialog = ref<HTMLDialogElement>(), editing = ref(false), editId = ref<number | null>(null), saving = ref(false), formError = ref('')
const form = reactive({ code: '', name: '', unit: '', min_stock_level: 0, supplier_id: null as number | null, is_active: true })
const tx = reactive({ ingredient_id: 0, type: 'EXPORT' as TxType, quantity: 0, expected_stock: 0, reason_code: 'SUPPLIER_RETURN', note: '', request_key: '' })
const selected = computed(() => items.value.find(i => i.id === tx.ingredient_id))
const transactions = ref<Transaction[]>([]), historyLoading = ref(false), historyError = ref(''), historyPage = ref(1), lastPage = ref(1)
const historyFilter = reactive({ ingredient_id: '' as number | '', type: '', from: '', to: '' })
let appliedFilter = { ...historyFilter }
const number = (n: number | string) => Number(n).toLocaleString('vi-VN', { maximumFractionDigits: 2 })
const date = (s: string) => new Date(s).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })
const message = (e: any) => Object.values(e?.response?.data?.errors || {}).flat().join(' ') || e?.response?.data?.message || 'Không xử lý được. Vui lòng thử lại.'
async function refresh(quiet = false) { if (loading.value) return; if (!quiet) loading.value = true; if (!quiet) error.value = ''; const fresh = beginRead(liveReads, 'list', quiet); try { const r = await api.get<{ data: Ingredient[]; suppliers: { id: number; name: string }[] }>('/staff/dashboard/ingredients'); if (!fresh()) return; error.value = ""; items.value = r.data.data; suppliers.value = r.data.suppliers } catch (e) { if (quiet) throw e; error.value = message(e) } finally { if (!quiet) loading.value = false }; if (!ingredientsMode.value) await loadHistory(quiet ? historyPage.value : 1, quiet) }
async function loadHistory(p = 1, quiet = false) { if (historyLoading.value) return; if (p === 1 && !quiet) appliedFilter = { ...historyFilter }; if (!quiet) historyLoading.value = true; historyError.value = ''; const fresh = beginRead(liveReads, 'history', quiet); try { const params = Object.fromEntries(Object.entries(appliedFilter).filter(([, v]) => v !== '')); const r = await api.get<{ data: Transaction[]; current_page: number; last_page: number }>('/staff/dashboard/inventory-transactions', { params: { ...params, page: p } }); if (!fresh()) return; transactions.value = r.data.data; historyPage.value = r.data.current_page; lastPage.value = r.data.last_page } catch (e) { if (quiet) throw e; historyError.value = message(e) } finally { if (!quiet) historyLoading.value = false } }
function edit(i?: Ingredient) { editing.value = true; editId.value = i?.id ?? null; Object.assign(form, { code: '', name: '', unit: '', min_stock_level: 0, supplier_id: null, is_active: true }, i || {}); formError.value = ''; dialog.value?.showModal() }
function movement(type: TxType, i?: Ingredient) { editing.value = false; Object.assign(tx, { type, ingredient_id: i?.id || 0, quantity: 0, expected_stock: i?.quantity_in_stock || 0, reason_code: type === 'EXPORT' ? 'SUPPLIER_RETURN' : 'DAMAGED', note: '', request_key: crypto.randomUUID() }); formError.value = ''; dialog.value?.showModal() }
function selectIngredient() { tx.expected_stock = selected.value?.quantity_in_stock || 0; tx.quantity = 0 }
function close() { if (!saving.value) dialog.value?.close() }
function cancel(e: Event) { if (saving.value) e.preventDefault() }
async function save() { if (saving.value) return; saving.value = true; formError.value = ''; try { if (editing.value) { if (editId.value) await api.patch('/staff/dashboard/ingredients/' + editId.value, form); else await api.post('/staff/dashboard/ingredients', form) } else await api.post('/staff/dashboard/inventory-transactions', tx); dialog.value?.close(); success.value = editing.value ? 'Đã lưu nguyên liệu.' : 'Đã ghi nhận phiếu và cập nhật tồn kho.'; await refresh() } catch (e) { formError.value = message(e) } finally { saving.value = false } }
watch([search, status], () => page.value = 1)
watch(() => route.path, () => { close(); success.value = ''; page.value = 1; void refresh() })
onMounted(refresh)
useRealtimeRefresh(() => refresh(true), () => !loading.value && !historyLoading.value && !saving.value)
</script>
<style scoped>
.stock-page { display: flex; flex-direction: column; gap: 20px; }.metrics { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }.metrics>div { padding: 22px; background: white; border: 1px solid var(--color-border); border-radius: 12px; display: flex; flex-direction: column; gap: 12px; }.metrics span { font-size: 13px; color: #64748b; }.metrics strong { font-size: 28px; color: var(--color-brand-ink); }.filters,.actions,.pagination { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }.filters>a { color: var(--color-brand-ink); font-size: 13px; }.filters>input { flex: 1; }.filters label { display: flex; flex-direction: column; gap: 4px; font-size: 12px; }.table-wrap { overflow-x: auto; background: white; border: 1px solid var(--color-border); border-radius: 12px; }table { border-collapse: collapse; width: 100%; min-width: 820px; font-size: 13px; }th,td { text-align: left; padding: 14px; border-bottom: 1px solid #edf1ee; }th { background: var(--color-brand-soft); color: #64748b; font-size: 12px; }small { display: block; color: #64748b; margin-top: 5px; }.number { font-variant-numeric: tabular-nums; }.tag { padding: 5px 8px; border-radius: 5px; background: #edf5ef; white-space: nowrap; }.tag.warn { color: #9a3412; background: #fff2df; }.history { display: flex; flex-direction: column; gap: 16px; }.history h3 { margin: 12px 0 0; }.note { max-width: 280px; white-space: pre-wrap; overflow-wrap: anywhere; }.pagination { justify-content: flex-end; font-size: 13px; }input,select,textarea { border: 1px solid var(--color-border-strong); border-radius: 7px; padding: 10px; font: inherit; min-width: 0; box-sizing: border-box; }.primary { background: var(--color-brand-action); color: white; }dialog { width: min(560px,calc(100% - 32px)); max-height: 90vh; border: 0; border-radius: 14px; padding: 0; color: var(--color-text); font: 14px var(--font-ui); }dialog::backdrop { background: color-mix(in srgb, var(--color-brand-dark) 75%, transparent); }dialog header,dialog footer { padding: 18px 24px; display: flex; align-items: center; justify-content: space-between; gap: 12px; border-bottom: 1px solid #e2e8f0; }dialog h3 { margin: 0; }dialog footer { justify-content: flex-end; border-top: 1px solid #e2e8f0; }.form-body { padding: 24px; }fieldset { display: flex; flex-direction: column; gap: 16px; padding: 0; margin: 0; border: 0; }fieldset label { display: flex; flex-direction: column; gap: 7px; }fieldset .check { flex-direction: row; align-items: center; }.help { color: #64748b; font-size: 12px; line-height: 1.7; margin: 0; }button { cursor: pointer; }button:disabled { opacity: .5; cursor: not-allowed; }@media(max-width:650px) { .metrics { grid-template-columns: 1fr; }.filters>input { width: 100%; } }
</style>
